"""Generate diagnostic tables exclusively from archived observations."""
from pathlib import Path
import json,statistics,collections
W=Path(__file__).resolve().parent
read=lambda p:json.loads((W/p).read_text())
cases=read('case-manifest.json');verify=read('verification.json');screen=read('screen-summary.json');confirm=[read(f'confirm-{n}-summary.json') for n in [1,2]]
profiles=read('profile-summary.json');counts=read('counters.json');probes=[read(f'probes/run-{n}-summary.json') for n in [1,2]]
cm=[{r['index']:r for r in run} for run in confirm];pm=[{r['index']:r for r in run} for run in probes]
def label(i):
 c=cases[i];s=c['case']
 if c['kind']=='concat':return s.replace('concat/','')
 if c['kind']=='control':return s
 return c['project']+'/'+s.rsplit('/',1)[-1]
def line(s=''):out.append(s)
def pct_range(values):return f'{min(values):.1f}–{max(values):.1f}%'
out=['# Generated corpus and profiling results','', 'Generated by `make-results.py`. Diagnostic data only; not the README/homepage benchmark dataset.','']
line('## Output coverage')
line();line('| Corpus | Original `.md` files | Input KiB | Normalized matches | Excluded files |');line('|---|---:|---:|---:|---:|')
for project in ['vue-docs','vite-docs','rust-book','typescript-handbook']:
 ids=[i for i,c in enumerate(cases) if c['project']==project and c['kind']=='file'];equal=sum(verify[i]['equal'] for i in ids)
 line(f'| {project} | {len(ids)} | {sum(cases[i]["bytes"] for i in ids)/1024:.1f} | {equal} | {len(ids)-equal} |')
ids=[i for i,c in enumerate(cases) if c['kind']=='file'];line(f'| Total | {len(ids)} | {sum(cases[i]["bytes"] for i in ids)/1024:.1f} | {sum(verify[i]["equal"] for i in ids)} | {sum(not verify[i]["equal"] for i in ids)} |')
line();line('All eight concatenations fail the normalizer contract and are diagnostic only. All three Ox parser fixtures pass. The collector includes Markdown license/readme files selected by upstream sparse-checkout patterns.')
line();line('## Confirmed comparable documents')
line();line('Microseconds per fresh parse + owned HTML + drop; median of two process medians. Ratio > 1 means Ferromark takes longer. The final column shows the two process ratios, not a confidence interval.')
line();line('| Document | KiB | Ferromark µs | Ox growing µs | Ox reserved µs | F / Ox growing | Process ratio range |');line('|---|---:|---:|---:|---:|---:|---:|')
for i in cm[0]:
 if not verify[i]['equal']:continue
 med={e:statistics.median(r[i]['median_ns'][e] for r in cm) for e in ['ferro','ox-grow','ox-presize']};ratios=[r[i]['median_ns']['ferro']/r[i]['median_ns']['ox-grow'] for r in cm]
 line(f'| {label(i)} | {cases[i]["bytes"]/1024:.1f} | {med["ferro"]/1000:.2f} | {med["ox-grow"]/1000:.2f} | {med["ox-presize"]/1000:.2f} | {med["ferro"]/med["ox-grow"]:.2f}× | {min(ratios):.2f}–{max(ratios):.2f}× |')
line();line('## Whole concatenations: diagnostic times, different HTML')
line();line('The upstream profile reproduces Ox `ParserOptions::gfm()` + `HtmlRenderer::new()`; Ferromark enables the corresponding syntax, but the output contracts differ. No ranking is inferred from this table. Sorted path order is our deterministic variant of upstream’s unspecified filesystem order.')
line();line('| Corpus / profile | KiB | Ferromark ms | Ox growing ms | Ox reserved ms |');line('|---|---:|---:|---:|---:|')
for i in cm[0]:
 if cases[i]['kind']!='concat':continue
 med={e:statistics.median(r[i]['median_ns'][e] for r in cm) for e in ['ferro','ox-grow','ox-presize']}
 line(f'| {label(i)} | {cases[i]["bytes"]/1024:.1f} | {med["ferro"]/1e6:.3f} | {med["ox-grow"]/1e6:.3f} | {med["ox-presize"]/1e6:.3f} |')
line();line('## Visible Ferromark CPU stacks')
line();line('Each row is one six-second capture. Percentages use all sampled stacks, including harness/runtime. Optimized inlining prevents these symbol groups from being exact phase timings. Allocation and sorting percentages overlap the other groups and must not be added to them.')
line();line('| Document / capture | Samples | Visible block frames | Visible inline frames | Allocation stacks | Emit-point sort stacks |');line('|---|---:|---:|---:|---:|---:|')
for r in profiles:
 if not r['file'].startswith('ferro-'):continue
 _,idx,capture=r['file'].split('-');i=int(idx);cap=capture.split('.')[0]
 stage=lambda n:r['stages'].get(n,{}).get('pct',0)
 line(f'| {label(i)} / {cap} | {r["total_samples"]} | {stage("visible block frames"):.1f}% | {stage("visible inline frames"):.1f}% | {r["allocation_stack_pct"]:.1f}% | {r["emit_sort_stack_pct"]:.1f}% |')
line();line('## Work counters on representative original documents')
line();line('Separate instrumentation build; never used for timing. Text-event counts include raw HTML. Counts describe work, not elapsed time or peak memory.')
line();line('| Document | Block events | Code events | Inline parses | Inline marks | Emit points | Paragraph bytes copied |');line('|---|---:|---:|---:|---:|---:|---:|')
for i in [34,63,114,442,568,625]:
 c=counts[i]['counts'];line(f'| {label(i)} | {c["block_events"]} | {c["block_code_events"]} | {c["inline_parses"]} | {c["inline_marks"]} | {c["inline_emit_points"]} | {c["paragraph_copied_bytes"]} |')
line();line('## Isolated line-scan prototypes')
line();line('Percent change versus the unchanged merged Ferromark baseline, shown separately for both timing passes. Negative is faster. `advance` replaces the scalar `find_line_end` loop with `memchr`; `peek` does the same for `current_line_slice`; `both` combines them. Each prototype preserves exact HTML for all 649 cases. These are diagnostic patches, not production changes or a cross-platform release validation.')
line();line('| Document | Advance: pass 1 / 2 | Peek: pass 1 / 2 | Both: pass 1 / 2 |');line('|---|---:|---:|---:|')
for i in pm[0]:
 cells=[f'{pm[0][i]["change_pct"][v]:+.1f}% / {pm[1][i]["change_pct"][v]:+.1f}%' for v in ['advance','peek','both']]
 line('| '+label(i)+' | '+' | '.join(cells)+' |')
line();line('The paired prototype passes reuse their four processes. The separate native confirmation runs restart processes. Near-zero and inconsistent changes are noise/screening evidence, not improvements.')
line();line('## Full-corpus screening context')
line();line('The short screen selected follow-up documents. These sums add per-file hot-loop medians for normalizer-passing files; they are not measurements of a site build, concatenated document, or one batch. Do not use them as a public ranking.')
line();line('| Corpus | Included files | Sum F ms | Sum Ox growing ms | Sum Ox reserved ms |');line('|---|---:|---:|---:|---:|')
for project in ['vue-docs','vite-docs','rust-book','typescript-handbook']:
 ids=[i for i,c in enumerate(cases) if c['project']==project and c['kind']=='file' and verify[i]['equal']]
 totals={e:sum(screen[i]['median_ns'][e] for i in ids)/1e6 for e in ['ferro','ox-grow','ox-presize']}
 line(f'| {project} | {len(ids)} | {totals["ferro"]:.3f} | {totals["ox-grow"]:.3f} | {totals["ox-presize"]:.3f} |')
(W/'RESULTS.md').write_text('\n'.join(out)+'\n')
print('Generated RESULTS.md')
